// core of DAILY-REPORT Build node; runs in n8n and locally for testing
function buildReport(P, startupRows, cals, nowMs, prev, sinceMs) {
  const s = v => String(v == null ? '' : v).trim();
  const nz = x => s(x).toLowerCase().replace(/[’']/g, '').replace(/\(.*?\)/g, '').replace(/[^a-z0-9]/g, '');
  const esc = x => s(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const GENERIC = /^(gmail|yahoo|hotmail|outlook|icloud|msn|live|rediffmail|protonmail|me|ymail|googlemail|aol)\./i;
  const doms = v => (s(v).match(/[A-Za-z0-9._%+'-]+@[A-Za-z0-9.-]+/g) || []).map(e => e.split('@')[1].toLowerCase()).filter(d => !GENERIC.test(d) && d !== 'sidanaventures.com');
  const IST = 5.5 * 3600e3;
  const today = new Date(nowMs + IST).toISOString().slice(0, 10);

  // startups + aliases
  const ALIAS = { aisignallabs: ['aisignallab'], caffenacoffee: ['caffena', 'caffeina', 'caffina'], orboai: ['orbo'], bodybeyond: ['bodyandbeyond'], sugarsdaddy: ['sugardaddy'], altfcoworking: ['altf'], springbaseai: ['springbase'], tronixai: ['tronix'], orbislives: ['orbis'], ekosight: ['ecosight'], firearmor: ['fireamor'] };
  const startups = startupRows.map(r => s(r[0])).filter(x => x && x.toLowerCase() !== 'startup');
  const skeys = startups.map(x => ({ s: x, k: [nz(x)].concat(ALIAS[nz(x)] || []) }));
  const findStartup = t => { const n = nz(t); let best = null; for (const x of skeys) for (const k of x.k) if (k.length >= 4 && n.includes(k) && (!best || k.length > best.len)) best = { s: x.s, len: k.length }; return best ? best.s : ''; };

  // calendar events (deduped across the 4 calendars)
  const evs = [], seenEv = new Set();
  for (const items of cals) for (const e of (items || [])) {
    if (e.status === 'cancelled' || !e.summary) continue;
    const st = (e.start && (e.start.dateTime || e.start.date)) || '';
    const key = nz(e.summary) + '|' + st.slice(0, 16);
    if (seenEv.has(key)) continue; seenEv.add(key);
    if (/interview|internal|onboarding|\bmou\b|task/i.test(e.summary)) continue;
    const su = findStartup(e.summary); if (!su) continue;
    evs.push({ su, t: nz(e.summary), title: e.summary, st, created: e.created || '', ms: Date.parse(st), doms: new Set((e.attendees || []).map(a => (s(a.email).split('@')[1] || '').toLowerCase()).filter(d => d && d !== 'sidanaventures.com' && !GENERIC.test(d))) });
  }

  // pipeline
  const h = P[0].map(s), I = k => h.indexOf(k), g = (r, k) => { const i = I(k); return i < 0 ? '' : s(r[i]); };
  const pairs = new Map();
  for (const r of P.slice(1)) {
    if (g(r, 'deal_shared') !== 'Yes') continue;
    const su = g(r, 'startup'), inv = g(r, 'investor'); if (!su || !inv) continue;
    const key = nz(su) + '|' + nz(inv.split(/\s+-\s+/)[0]);
    const x = pairs.get(key) || { su, inv, owner: g(r, 'owner'), date: g(r, 'date_shared'), last: '', resp: '', status: '', ms: '', doms: new Set() };
    for (const c of ['date_shared', 'last_contact']) { const v = g(r, c).slice(0, 10); if (/^\d{4}-\d\d-\d\d$/.test(v) && v > x.last) x.last = v; }
    if (g(r, 'investor_response')) x.resp = g(r, 'investor_response');
    if (g(r, 'deal_status')) x.status = g(r, 'deal_status');
    if (g(r, 'meeting_scheduled')) x.ms = g(r, 'meeting_scheduled');
    if (g(r, 'next_action')) x.na = g(r, 'next_action');
    if (g(r, 'date_shared') && (!x.date || g(r, 'date_shared') < x.date)) x.date = g(r, 'date_shared');
    doms(g(r, 'email') + ',' + g(r, 'cc')).forEach(d => x.doms.add(d));
    pairs.set(key, x);
  }
  const rows = [...pairs.values()];
  const sharesToday = P.slice(1).filter(r => g(r, 'deal_shared') === 'Yes' && g(r, 'date_shared').startsWith(today)).length;

  for (const x of rows) {
    const ik = nz(x.inv.split(/\s+-\s+/)[0]);
    const m = evs.filter(e => e.su === x.su && ([...e.doms].some(d => x.doms.has(d)) || (ik.length >= 4 && e.t.includes(ik)))).sort((a, b) => a.ms - b.ms);
    const both = (x.resp + ' ' + x.status);
    const sheetMeet = (/meeting/i.test(both) && !/request/i.test(both)) || /^yes/i.test(x.ms);
    x.meetAt = m.length ? m[0].st : '';
    x.meetUpcoming = m.length ? m.every(e => e.ms > nowMs) : false;
    const R = x.resp, St = x.status;
    if (/^bounced/i.test(R)) x.cat = 'bounced';
    else if (m.length || sheetMeet) x.cat = 'meeting';
    else if (/^meeting requested/i.test(R) || /^book meeting/i.test(x.na || '') || /(asked|wants|requested).{0,30}(meeting|call)|slots? (sent|shared|requested)/i.test(R)) x.cat = 'tobook'; // investor asked for a meeting, no invite yet (24 Sep: also catch next_action 'Book meeting' and plain-English requests, so a missing marker cannot hide one)
    else if (/^pass/i.test(R) || /^pass|not relevant/i.test(St)) x.cat = 'passed';
    else if (/refer|forward/i.test(R) || (!R && /refer/i.test(St))) x.cat = 'referred';
    else if (/not active|needs review/i.test(R)) x.cat = 'other';
    else if (/intrest|interest|question|asked|request|reviewing|under review|deck|document|form|excel|positive|call|evaluat/i.test(R) || (!R && /reviewing|question|docs/i.test(St))) x.cat = 'interested';
    else if (R) x.cat = 'other';
    else x.cat = 'none';
  }
  // all investor meetings this month (held + scheduled), from calendars
  const invByDom = {}, invByKey = {};
  for (const r of P.slice(1)) {
    const inv = g(r, 'investor'); if (!inv) continue;
    doms(g(r, 'email') + ',' + g(r, 'cc')).forEach(dm => { if (!invByDom[dm]) invByDom[dm] = inv; });
    const k = nz(inv.split(/\s+-\s+/)[0]); if (k.length >= 5 && !invByKey[k]) invByKey[k] = inv;
  }
  const monthKey = today.slice(0, 7);
  const monthName = new Date(nowMs + IST).toLocaleString('en-GB', { month: 'long', year: 'numeric', timeZone: 'UTC' });
  const invOf = e => {
    for (const dm of e.doms) if (invByDom[dm]) return invByDom[dm];
    const tt = e.t.replace(/michelle/g, 'michele');
    let best = ''; for (const k in invByKey) if (tt.includes(k) && k.length > best.length) best = k;
    if (best) return invByKey[best];
    if (e.title.includes('<>')) {
      // investor not in PIPELINE: take the other side of "X <> Y" from the title
      const side = e.title.split('<>').map(x => x.trim()).find(x => !nz(x).includes(nz(e.su).slice(0, 4))) || '';
      const clean = side.replace(/\|.*$/, '').replace(/\band\s+(sidana ventures|aditya sv).*$/i, '').replace(/\b(mr|ms|mrs)\.?\s+/ig, '').trim();
      if (clean && !/sidana|^rakesh/i.test(clean)) return clean;
    }
    return '';
  };
  const invMeet = [];
  for (const e of evs) { if (!e.st) continue; const inv = invOf(e); if (inv) invMeet.push({ ...e, inv, held: e.ms <= nowMs }); }
  invMeet.sort((a, b) => a.ms - b.ms);
  // reschedules: same startup + investor within 3 days counts once (the latest date is kept)
  { const kept = {}; for (let i = invMeet.length - 1; i >= 0; i--) { const x = invMeet[i]; const k = x.su + '|' + nz(x.inv).replace(/michelle/g, 'michele').slice(0, 6); if (kept[k] != null && kept[k] - x.ms < 3 * 864e5) invMeet.splice(i, 1); else kept[k] = x.ms; } }
  const monthMeet = invMeet.filter(x => new Date(x.ms + IST).toISOString().slice(0, 7) === monthKey);
  // booked since the last report went out (so bookings made after 6 PM are not lost); first run: since midnight IST
  const since = sinceMs || Date.parse(today + 'T00:00:00+05:30');
  const newToday = invMeet.filter(x => x.created && Date.parse(x.created) > since && !evs.some(e => e.su === x.su && e.ms === x.ms && e.created && Date.parse(e.created) <= since)); // 22 Sep: a second invite for a meeting already booked (e.g. the investor's own Teams invite) is not a new meeting
  const MM = { held: monthMeet.filter(x => x.held).length, sched: monthMeet.filter(x => !x.held).length };
  // ---- brief totals (calendar is the source for meetings) ----
  // MONTH SCOPE (Aditya, 5 Oct 2026): "send the data as per a particular month ... share him of
  // october from today". The report used to total everything since 31 Aug, so September kept
  // showing up in an October report. Now: deals shared are the month's own cohort by date_shared,
  // meetings are the month's own calendar events. Rolls over by itself on the 1st.
  const mrows = rows.filter(x => s(x.date).slice(0, 7) === monthKey);
  const calMeet = monthMeet;
  const sheetOnly = 0; // calendar is the only source: PIPELINE 'meeting' flags without an invite proved unreliable (21 Sep)
  // interested: split active vs gone quiet (no movement for 10+ days); a date written in the response text counts as movement
  const MON = { jan: '01', feb: '02', mar: '03', apr: '04', may: '05', jun: '06', jul: '07', aug: '08', sep: '09', oct: '10', nov: '11', dec: '12' };
  const lastAct = x => { let l = x.last || x.date; const m = x.resp.match(/\((\d{1,2}) (jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\)/i); if (m) { const v = today.slice(0, 4) + '-' + MON[m[2].toLowerCase()] + '-' + m[1].padStart(2, '0'); if (v > l) l = v; } return l; };
  const intr = mrows.filter(x => x.cat === 'interested');
  const quiet = intr.filter(x => (Date.parse(today) - Date.parse(lastAct(x))) / 864e5 > 10).length;
  const T = {
    shares: mrows.length,
    responses: mrows.filter(x => !['none', 'bounced'].includes(x.cat)).length,
    passes: mrows.filter(x => x.cat === 'passed').length,
    meetings: calMeet.length + sheetOnly + mrows.filter(x => x.cat === 'tobook').length,
    meetToBook: mrows.filter(x => x.cat === 'tobook').length,
    meetHeld: calMeet.filter(x => x.held).length + sheetOnly,
    meetSched: calMeet.filter(x => !x.held).length,
    interested: intr.length - quiet,
    quiet,
    sharesToday,
    newMeet: newToday.length,
    monthHeld: MM.held, monthSched: MM.sched,
  };
  const pct = (a, b) => b ? Math.round(100 * a / b) + '%' : '-';
  const d = k => prev && prev[k] != null ? (T[k] - prev[k] >= 0 ? '+' : '') + (T[k] - prev[k]) : '';
  const td = 'style="padding:6px 12px;border-bottom:1px solid #ddd"';
  const tdn = 'style="padding:6px 12px;border-bottom:1px solid #ddd;text-align:right"';
  const tdd = 'style="padding:6px 12px;border-bottom:1px solid #ddd;text-align:right;color:#666"';
  const th = 'style="text-align:left;padding:6px 12px;border-bottom:2px solid #222;background:#f3f3f3"';
  const row = (label, val, key) => `<tr><td ${td}>${label}</td><td ${tdn}><b>${val}</b></td><td ${tdd}>${key ? d(key) : ''}</td></tr>`;
  const dateLabel = new Date(nowMs + IST).toUTCString().slice(0, 16);
  const html = `<div dir="ltr" style="font-family:Arial,Helvetica,sans-serif;font-size:small;color:#222222">
<div>Hi Rakesh,</div><div><br></div>
<div>Daily deal update for ${esc(dateLabel)}. All figures below are for ${esc(monthName)} only.</div><div><br></div>
<table style="border-collapse:collapse;font-size:small;margin:6px 0 16px">
<tr><th ${th}></th><th ${th}>${esc(monthName)}</th><th ${th}>Since last report</th></tr>
${row('Deals shared', T.shares, 'shares')}
${row('Investor responses', T.responses + ' (' + pct(T.responses, T.shares) + ')', 'responses')}
${row('Passes', T.passes, 'passes')}
${row('Meetings', T.meetings + ' (' + T.meetHeld + ' held, ' + T.meetSched + ' scheduled' + (T.meetToBook ? ', ' + T.meetToBook + ' yet to be booked' : '') + ')', 'meetings')}
${row('Interested, no meeting yet', T.interested, 'interested')}
${row('Interested but gone quiet (10+ days)', T.quiet, 'quiet')}
</table>
<table style="border-collapse:collapse;font-size:small;margin:6px 0 16px">
<tr><th ${th}>Today</th><th ${th}></th></tr>
<tr><td ${td}>Deals shared today</td><td ${tdn}><b>${T.sharesToday}</b></td></tr>
<tr><td ${td}>New meetings booked</td><td ${tdn}><b>${T.newMeet}</b></td></tr>
</table>
<div>Meetings per 100 deals shared: <b>${(100 * T.meetings / Math.max(T.shares, 1)).toFixed(1)}</b> (goal: 80).</div><div><br></div>
</div>`;
  return { T, html, subject: 'Sidana Ventures | Daily deal report | ' + dateLabel };
}

